module max_revenue (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] N,\n    input [9:0] S_0,\n    input [9:0] S_1,\n    input [9:0] S_2,\n    input [9:0] S_3,\n    input [9:0] S_4,\n    input [9:0] S_5,\n    input [9:0] S_6,\n    input [9:0] S_7,\n    input [9:0] S_8,\n    input [9:0] S_9,\n    input [9:0] S_10,\n    input [9:0] S_11,\n    input [9:0] S_12,\n    input [9:0] S_13,\n    output reg [6:0] result,\n    output reg done\n);\n    \n    // FSM states\n    localparam [3:0] IDLE        = 4'd0;\n    localparam [3:0] INIT_START  = 4'd1;\n    localparam [3:0] INIT_SUM    = 4'd2;\n    localparam [3:0] INIT_OMEGA  = 4'd3;\n    localparam [3:0] INIT_NEXT   = 4'd4;\n    localparam [3:0] DP_START    = 4'd5;\n    localparam [3:0] DP_OUTER    = 4'd6;\n    localparam [3:0] DP_INNER    = 4'd7;\n    localparam [3:0] DP_NEXT     = 4'd8;\n    localparam [3:0] DP_STORE    = 4'd9;\n    localparam [3:0] DONE        = 4'd10;\n    \n    reg [3:0] state, next_state;\n    \n    // S inputs storage\n    reg [9:0] S [0:13];\n    \n    // Memories\n    reg [13:0] subset_sum [0:16383]; // 14 bits\n    reg [2:0]  subset_omega [0:16383]; // 3 bits\n    reg [6:0]  dp [0:16383]; // 7 bits\n    \n    // Prime list ROM (primes <= 118)\n    localparam [6:0] PRIMES [0:29] = '{7'd2, 7'd3, 7'd5, 7'd7, 7'd11, 7'd13, 7'd17, 7'd19, 7'd23, 7'd29, 7'd31, 7'd37, 7'd41, 7'd43, 7'd47, 7'd53, 7'd59, 7'd61, 7'd67, 7'd71, 7'd73, 7'd79, 7'd83, 7'd89, 7'd97, 7'd101, 7'd103, 7'd107, 7'd109, 7'd113};\n    \n    // Counters/temp regs\n    reg [13:0] mask;\n    reg [13:0] max_mask;\n    reg [13:0] sub_mask;\n    reg [6:0]  max_val;\n    reg [13:0] mask_minus_lsb;\n    reg [13:0] lsb_mask;\n    reg [3:0]  lsb_idx;\n    reg [13:0] current_sum;\n    reg [4:0]  prime_idx;\n    reg [2:0]  omega_count;\n    reg [13:0] dp_mask;\n    reg [6:0]  candidate;\n    \n    // Loop counters\n    integer i;\n    \n    // FSM state register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 7'd0;\n            done <= 1'b0;\n            mask <= 14'd0;\n            max_mask <= 14'd0;\n            sub_mask <= 14'd0;\n            max_val <= 7'd0;\n            mask_minus_lsb <= 14'd0;\n            lsb_mask <= 14'd0;\n            lsb_idx <= 4'd0;\n            current_sum <= 14'd0;\n            prime_idx <= 5'd0;\n            omega_count <= 3'd0;\n            dp_mask <= 14'd0;\n            candidate <= 7'd0;\n            // Initialize memories to zero\n            for(i=0; i<16384; i=i+1) begin\n                subset_sum[i] <= 14'd0;\n                subset_omega[i] <= 3'd0;\n                dp[i] <= 7'd0;\n            end\n            // Initialize S array\n            for(i=0; i<14; i=i+1) begin\n                S[i] <= 10'd0;\n            end\n        end else begin\n            case(state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Latch S inputs\n                        S[0]  <= S_0;\n                        S[1]  <= S_1;\n                        S[2]  <= S_2;\n                        S[3]  <= S_3;\n                        S[4]  <= S_4;\n                        S[5]  <= S_5;\n                        S[6]  <= S_6;\n                        S[7]  <= S_7;\n                        S[8]  <= S_8;\n                        S[9]  <= S_9;\n                        S[10] <= S_10;\n                        S[11] <= S_11;\n                        S[12] <= S_12;\n                        S[13] <= S_13;\n                        max_mask <= (14'd1 << N) - 14'd1;\n                        mask <= 14'd1;\n                    end\n                end\n                \n                INIT_START: begin\n                    mask <= 14'd1;\n                    max_mask <= (14'd1 << N) - 14'd1;\n                end\n                \n                INIT_SUM: begin\n                    // Find LSB index and compute sum\n                    lsb_mask <= mask & -mask;\n                    for(i=0; i<14; i=i+1) begin\n                        if(lsb_mask[i]) lsb_idx <= i;\n                    end\n                    mask_minus_lsb <= mask ^ lsb_mask;\n                    subset_sum[mask] <= subset_sum[mask_minus_lsb] + S[lsb_idx];\n                    current_sum <= subset_sum[mask_minus_lsb] + S[lsb_idx];\n                end\n                \n                INIT_OMEGA: begin\n                    if(prime_idx < 5'd30) begin\n                        if(PRIMES[prime_idx] <= current_sum) begin\n                            if(current_sum % {7'd0, PRIMES[prime_idx]} == 14'd0) begin\n                                omega_count <= omega_count + 3'd1;\n                            end\n                        end\n                        prime_idx <= prime_idx + 5'd1;\n                    end\n                end\n                \n                INIT_NEXT: begin\n                    subset_omega[mask] <= omega_count;\n                    omega_count <= 3'd0;\n                    prime_idx <= 5'd0;\n                    mask <= mask + 14'd1;\n                end\n                \n                DP_START: begin\n                    dp[0] <= 7'd0;\n                    dp_mask <= 14'd1;\n                end\n                \n                DP_OUTER: begin\n                    sub_mask <= dp_mask;\n                    max_val <= 7'd0;\n                end\n                \n                DP_INNER: begin\n                    candidate <= dp[dp_mask ^ sub_mask] + subset_omega[sub_mask];\n                    if(candidate > max_val) max_val <= candidate;\n                end\n                \n                DP_NEXT: begin\n                    sub_mask <= (sub_mask - 14'd1) & dp_mask;\n                end\n                \n                DP_STORE: begin\n                    dp[dp_mask] <= max_val;\n                    dp_mask <= dp_mask + 14'd1;\n                end\n                \n                DONE: begin\n                    result <= dp[max_mask];\n                    done <= 1'b1;\n                end\n            endcase\n            state <= next_state;\n        end\n    end\n    \n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case(state)\n            IDLE:       if(start) next_state = INIT_START;\n            INIT_START: next_state = INIT_SUM;\n            INIT_SUM:   next_state = INIT_OMEGA;\n            INIT_OMEGA: if(prime_idx == 5'd30) next_state = INIT_NEXT;\n            INIT_NEXT:  if(mask > max_mask) next_state = DP_START; else next_state = INIT_SUM;\n            DP_START:   next_state = DP_OUTER;\n            DP_OUTER:   next_state = DP_INNER;\n            DP_INNER:   next_state = DP_NEXT;\n            DP_NEXT:    if(sub_mask == 14'd0) next_state = DP_STORE; else next_state = DP_INNER;\n            DP_STORE:   if(dp_mask > max_mask) next_state = DONE; else next_state = DP_OUTER;\n            DONE:       next_state = IDLE;\n            default:    next_state = IDLE;\n        endcase\n    end\n    \nendmodule